/*
 * config.h - libloragw (SX1301, lora_gateway v5.0.1) build configuration.
 *
 * On Linux this file is generated by libloragw/Makefile from library.cfg
 * ("make" writes inc/config.h). The ESP-IDF build has no such step, so it is
 * kept here by hand, like in the SX1302 port (esxp1302).
 *
 * DEBUG_* = 1 makes a module very verbose (printf on every SPI access for
 * DEBUG_SPI): only for bench tests, never in production.
 */
#ifndef _LORAGW_CONFIGURATION_H
#define _LORAGW_CONFIGURATION_H

#define LIBLORAGW_VERSION   "5.0.1"
#define DEBUG_AUX           0
#define DEBUG_SPI           0
#define DEBUG_REG           0
#define DEBUG_HAL           0
#define DEBUG_GPS           0
#define DEBUG_GPIO          0
#define DEBUG_LBT           0

#endif
